from __future__ import absolute_import
from taf.selenium.sbts.pages import v26r1


class ConfigurationAutomationPage(v26r1.configuration.configuration_management.configuration_automation.ConfigurationAutomationPage):

    def __init__(self, driver):
        super(ConfigurationAutomationPage, self).__init__(driver)
        self._view_panel = ConfigurationAutomationPageViewPanel(driver)


class ConfigurationAutomationPageViewPanel(v26r1.configuration.configuration_management.configuration_automation.ConfigurationAutomationPageViewPanel):

    _CALCULATE = '//otx-operation-button//span[contains(text(), "Calculate")]'
    _APPLY_ALL = '//otx-operation-button//button[.//span[text()="Apply All"]]'
    _APPLY_ALL_STATUS = '//otx-operation-button//ot-instruction//span'
